/// Upstream semantic-code documentation.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct SemanticErrorSpec {
    /// Semantic code.
    pub code: ErrorCode,
    /// Exact Python remediation.
    pub remediation: &'static str,
    /// Exact Python long-form explanation.
    pub explanation: &'static str,
    /// Catalog documentation URL.
    pub docs_url: &'static str,
    /// Catalog Markdown URL.
    pub markdown_url: &'static str,
}

/// Exact chain-error documentation and source references.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ChainErrorSpec {
    /// Exact chain variant name.
    pub name: &'static str,
    /// Semantic classification.
    pub code: ErrorCode,
    /// Exact catalog description.
    pub description: &'static str,
    /// Catalog documentation URL.
    pub docs_url: &'static str,
    /// Catalog Markdown URL.
    pub markdown_url: &'static str,
    /// Pallets exposing the error.
    pub pallets: &'static [&'static str],
    /// Complete catalog source references as canonical JSON.
    pub sources_json: Option<&'static str>,
    /// Complete untouched catalog record as canonical JSON.
    pub catalog_json: &'static str,
}

