/// Ordered fallback needles used only when no chain name is available.
#[doc(alias = "bittensor.result._SUBSTRING_FALLBACK")]
pub const SUBSTRING_FALLBACK: &[(&str, ErrorCode)] = &[
    ("balance too low", ErrorCode::InsufficientBalance),
    ("inability to pay some fees", ErrorCode::InsufficientBalance),
    ("insufficient", ErrorCode::InsufficientBalance),
    ("not enough", ErrorCode::InsufficientBalance),
    ("rate limit", ErrorCode::RateLimited),
    ("too fast", ErrorCode::RateLimited),
    ("priority is too low", ErrorCode::RateLimited),
    ("already imported", ErrorCode::AlreadyExists),
    ("bad signature", ErrorCode::InvalidArgument),
    ("invalid transaction", ErrorCode::InvalidArgument),
];

/// Look up an exact chain or dispatch error name.
pub fn chain_error_code(name: &str) -> Option<ErrorCode> {
    NAME_TO_CODE
        .iter()
        .chain(DISPATCH_ERRORS)
        .find_map(|(known, code)| (*known == name).then_some(*code))
}

/// Classify a named error using Python's exact-name and rate-limit rules.
pub fn classify_chain_error(name: &str) -> ErrorCode {
    classify_error("", Some(name))
}

/// Classify an error with Python's named-before-text precedence.
#[doc(alias = "bittensor.result.classify_error")]
pub fn classify_error(text: &str, name: Option<&str>) -> ErrorCode {
    if let Some(name) = name.filter(|name| !name.is_empty()) {
        if let Some(code) = chain_error_code(name) {
            return code;
        }
        if name.ends_with("RateLimitExceeded") || name.contains("RateLimit") {
            return ErrorCode::RateLimited;
        }
        return ErrorCode::Unknown;
    }
    let text = text.to_lowercase();
    SUBSTRING_FALLBACK
        .iter()
        .find_map(|(needle, code)| text.contains(needle).then_some(*code))
        .unwrap_or(ErrorCode::Unknown)
}

