/// Resolve a custom transaction code through the extracted exact table.
pub fn custom_transaction_name(code: u8) -> Option<&'static str> {
    CUSTOM_TRANSACTION_ERRORS
        .iter()
        .find_map(|(known, name)| (*known == code).then_some(*name))
}

/// Resolve a standard invalid-transaction display message, case-insensitively.
pub fn invalid_transaction_name(text: &str) -> Option<&'static str> {
    let text = text.to_lowercase();
    INVALID_TRANSACTION_ERRORS
        .iter()
        .find_map(|(needle, name)| text.contains(needle).then_some(*name))
}
